async function txt(parent, str, size, weight, color, x, y){
  const st = weight==='Bold'?'Bold':(weight==='Medium'?'Medium':'Regular');
  await figma.loadFontAsync({family:'Urbanist',style:st});
  const t = figma.createText();
  t.fontName={family:'Urbanist',style:st};
  t.characters=String(str);
  t.fontSize=size;
  t.fills=[{type:'SOLID',color:hex(color)}];
  t.x=x; t.y=y;
  parent.appendChild(t);
  return t;
}
