// reusable tab bar component
function buildTabBar(active){
  const tb=figma.createFrame(); tb.resize(428,80); fill(tb,C.surf); tb.name='Tab Bar';
  tb.layoutMode='HORIZONTAL'; tb.primaryAxisAlignItems='SPACE_BETWEEN'; tb.counterAxisAlignItems='CENTER'; tb.paddingLeft=40; tb.paddingRight=40; tb.y=846;
  tb.strokes=[{type:'SOLID',color:hex(C.line)}]; tb.strokeWeight=1; tb.cornerRadius={topLeft:16,topRight:16,bottomLeft:0,bottomRight:0};
  const tabs=[['Home','Icon_Home'],['Explore','Icon_Explore'],['Library','Icon_Library']];
  tabs.forEach(([label,icn])=>{
    const item=figma.createFrame(); item.layoutMode='VERTICAL'; item.counterAxisAlignItems='CENTER'; item.itemSpacing=6; tb.appendChild(item);
    const ic=inst(icn); ic.resize(26,26); ic.name=label+' icon';
    const col = (label===active)? hex(C.brand):hex(C.text3);
    ic.children.forEach(ch=>{ if(ch.type==='VECTOR'){ ch.fills=[{type:'SOLID',color:(label===active)?hex(C.brand):hex(C.text3)}]; } });
    // recolor vector fills within
    function recol(n,c){ n.fills=[{type:'SOLID',color:c}]; }
    function walkV(n){ if(n.type==='VECTOR')recol(n,(label===active)?hex(C.brand):hex(C.text3)); if('children'in n)n.children.forEach(walkV); }
    walkV(ic);
    item.appendChild(ic);
    const l=figma.createText(); l.fontName={family:'Urbanist',style:active===label?'Bold':'Medium'}; l.characters=label; l.fontSize=11; l.fills=[{type:'SOLID',color:(label===active)?hex(C.brand):hex(C.text2)}]; item.appendChild(l);
  });
  return tb;
}

