function findComp(name){ let f=null; function w(n){ if((n.type==='COMPONENT'||n.type==='COMPONENT_SET')&&n.name===name&&!f)f=n; if('children'in n)n.children.forEach(w); } F.root.children.forEach(w); return f; }

function txt(parent,x,y,str,size,weight,color){
  const t=F.createText();
  t.x=x; t.y=y;
  t.fontName={family:'Urbanist',style:weight};
  t.fontSize=size;
  t.fills=[{type:'SOLID',color:(()=>{const o={};hexRGB(color,o);return o;})()}];
  t.characters=str;
  t.textAutoResize='WIDTH_AND_HEIGHT';
  parent.appendChild(t);
  return t;
}
function rect(parent,x,y,w,h,color,rx){
  const n=figma.createRectangle();
  n.x=x; n.y=y; n.resize(w,h);
  n.fills=[{type:'SOLID',color:(()=>{const o={};hexRGB(color,o);return o;})(),opacity:1}];
  n.cornerRadius=rx||0;
  parent.appendChild(n);
  return n;
}

